local BASE_SCRIPT = enc {
struct Label {
    id: ""
    text: ""
    x: 0
    y: 0
    w: 0
    h: 0
    fontSize: 14
    opacity: 100
}

struct PieSlice {
    id: ""
    idx: 0
    name: ""
    value: 0
    percent: 10
    color: "#ff00ff"
    angle: 0
    labels: List()
}

func alignSlices(slices, initialAngle, shouldSort) {
    local total = 0

    slices.forEach((slice, idx) => {
        total += slice.value
    })

    if (total < 0.0000001) {
        total = 0.0000001
    }

    slices.forEach((slice, idx) => {
        slice.percent = slice.value * 100 / total
    })

    if (shouldSort) {
        slices.sort((a, b) => {
            b.percent - a.percent
        })
    }

    local allPrevPercents = 0
    slices.forEach((slice) => {
        local percent = slice.percent
        slice.angle = initialAngle + 360 * allPrevPercents / 100

        allPrevPercents += percent
    })
}

func buildSliceLabels(slices, chartX, chartY, chartWidth, chartHeight) {
    local labels = List()
    local r = min(chartWidth, chartHeight) / 2
    local lever = r * 0.8
    if (lever < 50) {
        lever = r * 0.5
    }
    slices.forEach((slice) => {
        local nicePercent = round(slice.percent)
        local labelText = `${nicePercent}%`
        local size = calculateTextSize(labelText, font, fontSize)
        local arcSize = 2 * PI() * lever * slice.percent / 100
        local avgLabelSize = (size.w + size.h) / 2
        local opacity = if (arcSize > avgLabelSize) { 100 } else { 0 }
        local midAngle = (270 + slice.angle + (slice.percent / 2) * 360 / 100) * PI() / 180
        local cx = cos(midAngle) * lever
        local cy = sin(midAngle) * lever
        local w = size.w * 1.3
        local h = size.h * 1.3
        local x = cx - w/2 + chartX + chartWidth/2
        local y = cy - h/2 + chartY + chartHeight/2
        labels.add(Label(`slice-label-percent-${slice.id}`, labelText, x, y, w, h, fontSize, opacity))
    })
    labels
}
} // end of baseScript


struct Legend {
    x: 0
    y: 0
    w: 0
    h: 0
    entries: List()
}

struct LegendEntry {
    id: ""
    x: 0
    y: 0
    w: 0
    h: 0
    name: ""
    color: "#FF00FFFF"
}


func buildLegend(data) {
    local maxWidth = 0
    local maxHeight = 0
    local entries = data.map((entry) => {
        local size = calculateTextSize(entry.name, font, fontSize)
        local w = size.w * 1.3
        local h = size.h * 1.3
        maxWidth = max(maxWidth, w)
        maxHeight = max(maxHeight, h)
        LegendEntry(entry.id, 0, 0, w, h, entry.name, entry.color)
    })

    local legendWidth = min(width/2, maxWidth + 40)
    local legendHeight = min(height, (maxHeight + legendSpacing * 2) * data.size)

    entries.forEach((entry, idx) => {
        entry.y = (maxHeight + legendSpacing * 2) * idx
        entry.h = maxHeight + legendSpacing * 2
    })

    Legend(width - legendWidth - padding, height/2 - legendHeight/2, legendWidth, legendHeight, entries)
}


func dataToSlices(data) {
    data.map((entry, idx) => {
        PieSlice(
            entry.id,
            idx,
            entry.name,
            entry.value,
            0, // percent
            entry.color,
            0 // angle
        )
    })
}

local slices = dataToSlices(data)
alignSlices(slices, initialAngle, true)

local legend = buildLegend(data)

local chartWidth = max(1, width - legend.w - padding*3)
local chartHeight = max(1, height - padding*2)
local sliceLabels = buildSliceLabels(slices, padding, padding, chartWidth, chartHeight)




struct PieAnimation {
    srcSlices: Map()
    dstSlices: Map()
    sliceItems: List()
}

func animationUpdatePie(pieAnimation, t) {
    pieAnimation.sliceItems.forEach((item) => {
        local idx = item.getVar('idx')

        local srcSlice = pieAnimation.srcSlices.get(idx)
        local dstSlice = pieAnimation.dstSlices.get(idx)
        if (srcSlice && dstSlice) {
            local angle = srcSlice.angle * (1 - t) + dstSlice.angle * t
            local percent = srcSlice.percent * (1 - t) + dstSlice.percent * t
            item.setAngle(angle)
            item.setPercent(percent)
        }
    })
}

func animationUpdatePieInit(sliceItemMap, sliceValues, initialAngle) {
    local sliceItems = findChildItemsByTag('pie-chart-slice')

    local dstTotal = 0
    sliceValues.forEach((value) => {
        dstTotal += value
    })
    if (dstTotal < 0.0000001) {
        dstTotal = 0.0000001
    }

    local slices = sliceItems.map((item) => {
        local sliceIdx = item.getVar('idx')
        local srcValue = item.getVar('value')
        local srcPercent = item.getVar('percent')
        sliceItemMap.set(sliceIdx, item)

        PieSlice(
            "",
            sliceIdx,
            item.getVar("name"),
            srcValue,
            srcPercent,
            '#FF00FFFF',
            item.getAngle(),
            List()
        )
    })
    alignSlices(slices, initialAngle, false)

    local dstSlices = slices.map((slice) => {
        local dstValue = if (slice.idx < sliceValues.size) { sliceValues.get(slice.idx) } else { 0 }
        local dstPercent = dstValue * 100 / dstTotal

        PieSlice(
            "",
            slice.idx,
            slice.name
            dstValue,
            dstPercent,
            slice.color,
            slice.angle,
            List()
        )
    })
    alignSlices(dstSlices, initialAngle, false)

    local srcSliceMap = Map()
    slices.forEach((slice) => { srcSliceMap.set(slice.idx, slice) })
    local dstSliceMap = Map()
    dstSlices.forEach((slice) => { dstSliceMap.set(slice.idx, slice) })
    PieAnimation(srcSliceMap, dstSliceMap, sliceItems)
}

func animationUpdatePieEnd() {
    pieAnimation.sliceItems.forEach((item) => {
        local idx = item.getVar('idx')

        local dstSlice = pieAnimation.dstSlices.get(idx)
        if (dstSlice) {
            item.setVar('value', dstSlice.value)
            item.setVar('percent', dstSlice.percent)
        }
    })
}

local changeAnimationInitScript = `
${BASE_SCRIPT}
${enc animationUpdatePie}
${enc animationUpdatePieInit}
${enc animationUpdatePieEnd}
${enc PieAnimation}
local initialAngle = ${initialAngle}

local sliceValues = values.split(',').map(parseFloat)

local sliceItemMap = Map()
local pieAnimation = animationUpdatePieInit(sliceItemMap, sliceValues, initialAngle)

`

local changeAnimationLoopScript = `
animationUpdatePie(pieAnimation, t)
`

local changeAnimationEndScript = `
animationUpdatePieEnd(pieAnimation)
`
